def cmd_query_contract(args: argparse.Namespace, conn: sqlite3.Connection) -> int:
    contract, changes, milestones = query_contract(conn, args.code)
    amount = current_cents(conn, contract["id"])
    print(f"合同编号：{contract['code']}")
