        print("里程碑：")
        for ms in milestones:
            ms_amount = milestone_current_cents(conn, ms["id"])
            print(
                f"  - {ms['code']}  名称：{ms['name']}  "
                f"到期日：{ms['due_date']}  当前金额：{format_yuan(ms_amount)}"
            )
    else:
        print("里程碑：无")
