        print("变更单：")
        for ch in changes:
            owner = ch["milestone_code"] if ch["milestone_code"] else "合同"
            print(
                f"  - {ch['code']}  变动：{format_yuan(ch['delta_cents'])}  "
                f"状态：{STATUS_LABELS[ch['status']]}  归属：{owner}"
            )
    else:
        print("变更单：无")
    return 0

